'use client';
import { useEffect, useRef, useState, type RefObject } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';
import { useInView, useStudioMotion } from '../../../motion';
import { StudioCanvas } from '../../../three';
import { resolveParams, type EffectMeta, type ParamValues } from '../../../types';
import SplitLineReveal from '../../../effects/split-line-reveal';
import { meta as splitMeta } from '../../../effects/split-line-reveal/meta';
import { Poster } from './Poster';
import { Scene, type Bridge, type Palette } from './Scene';
import { VIEWPOINTS, type StopId } from './terrain';
import s from './styles.module.css';

if (typeof window !== 'undefined') gsap.registerPlugin(ScrollTrigger, useGSAP);

/** Every recipe param from its meta (defaults), then this demo's overrides. */
const recipe = <T,>(m: EffectMeta, overrides: ParamValues = {}): T => resolveParams(m.params, overrides) as unknown as T;

const CHAPTERS = [
  { id: 'lake', label: 'Lake', time: '21:30', title: 'Lake Kelda at dusk', body: 'We meet at the boathouse while the ridge is still a silhouette. Twenty minutes to let your eyes adjust; head torches stay on red from here on.', meta: 'Start · the lake shore' },
  { id: 'ridge', label: 'Ridge', time: '22:10', title: 'The ridge path', body: 'Two hours on a marked path that never leaves the crest. The contour lines below you are the only map you need, and the guide carries the paper one anyway.', meta: 'About 6 km there and back' },
  { id: 'sky', label: 'Sky', time: '23:40', title: 'Under the northern sky', body: 'On some clear winter nights the sky over the ridge moves. We can’t promise it, and we never charge extra for it. The stars are reliable.', meta: 'Turning point · the summit cairn' },
] as const satisfies readonly { id: StopId; label: string; time: string; title: string; body: string; meta: string }[];

const WALKS = [
  ['Fri 4 Dec 2026', '20:30', '3 h 30', '12'],
  ['Sat 19 Dec 2026', '20:00', '4 h', '12'],
  ['Fri 15 Jan 2027', '20:30', '3 h 30', '10'],
  ['Sat 13 Feb 2027', '21:00', '4 h', '12'],
] as const;

/** Rest zones: the camera holds at each chapter's stop while its caption crosses the middle of the screen. */
const HOLD = 0.05;
function toU(p: number, c: readonly number[]): number {
  if (c.length < 4) return p;
  for (let k = 0; k < 3; k++) {
    const a = c[k] + HOLD;
    const b = c[k + 1] - HOLD;
    if (p <= a) return k / 3;
    if (p < b) { const f = (p - a) / (b - a); return (k + f * f * (3 - 2 * f)) / 3; }
  }
  return 1;
}

/** Scene colours come from the theme tokens (via the demo's --kr-* variables), re-read when the theme changes. */
function usePalette(ref: RefObject<HTMLElement | null>): Palette | null {
  const [palette, setPalette] = useState<Palette | null>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const read = () => {
      const cs = getComputedStyle(el);
      const v = (name: string, fb: string) => cs.getPropertyValue(name).trim() || fb;
      setPalette({
        base: v('--kr-base', '#f3f0e8'), line: v('--s3-ink-muted', '#5c5a52'), index: v('--s3-ink', '#11110f'), water: v('--kr-water', '#e9e5da'),
        skyTop: v('--kr-sky-top', '#e9e5da'), horizon: v('--kr-horizon', '#f3f0e8'), aurA: v('--kr-aur-a', '#0a6e4d'), aurB: v('--kr-aur-b', '#bf2f09'),
        route: v('--s3-signal', '#bf2f09'), stars: v('--s3-ink', '#11110f'), aurora: Number.parseFloat(v('--kr-aurora', '1')) || 1,
      });
    };
    read();
    const mo = new MutationObserver(read);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    return () => mo.disconnect();
  }, [ref]);
  return palette;
}

function WalksTitle() {
  const ref = useRef<HTMLDivElement>(null);
  const near = useInView(ref, { amount: 0.6 });
  const { reduced } = useStudioMotion();
  const text = 'Four walks this winter.';
  return (
    <div ref={ref} className={s.walksTitle}>
      {near || reduced ? <SplitLineReveal params={recipe(splitMeta, { text, stagger: 60, duration: 820, rise: 112, skew: false })} /> : <h2 className={s.placeholder}>{text}</h2>}
    </div>
  );
}

export default function Immersive3DHero() {
  const { reduced } = useStudioMotion();
  const root = useRef<HTMLDivElement>(null);
  const journey = useRef<HTMLDivElement>(null);
  const bridge = useRef<Bridge>({ u: 0, invalidate: null }).current;
  const live = useRef<{ st: ScrollTrigger; centers: () => readonly number[] } | null>(null);
  const [playing, setPlaying] = useState(true);
  const [off3d, setOff3d] = useState(false);
  const [active, setActive] = useState(0);
  const [stop, setStop] = useState<StopId>('lake');
  const palette = usePalette(root);
  const animate = playing && !reduced;

  useGSAP(() => {
    const el = root.current;
    const j = journey.current;
    if (reduced || !el || !j) return;
    const slides = gsap.utils.toArray<HTMLElement>('[data-slide]', j);
    let centers: number[] = [];
    const measure = (self: ScrollTrigger) => {
      const span = Math.max(1, self.end - self.start);
      const mid = 44 + (window.innerHeight - 44) / 2;
      centers = slides.map((x) => {
        const r = x.getBoundingClientRect();
        return gsap.utils.clamp(0, 1, (r.top + window.scrollY + r.height / 2 - mid - self.start) / span);
      });
    };
    const update = (self: ScrollTrigger) => {
      bridge.u = toU(self.progress, centers);
      bridge.invalidate?.();
      let best = 0;
      centers.forEach((c, i) => { if (Math.abs(c - self.progress) < Math.abs(centers[best] - self.progress)) best = i; });
      setActive((prev) => (prev === best ? prev : best));
    };
    const st = ScrollTrigger.create({ trigger: j, start: 'top top+=44', end: 'bottom bottom', onRefresh: (self) => { measure(self); update(self); }, onUpdate: update });
    measure(st);
    update(st);
    live.current = { st, centers: () => centers };

    // Layered type: the three title layers drift apart at different depths as the hero leaves.
    gsap.to(gsap.utils.toArray<HTMLElement>('[data-depth]', j), {
      yPercent: (i: number) => [-90, -48, -20][i] ?? 0,
      ease: 'none',
      scrollTrigger: { trigger: slides[0], start: 'top top+=44', end: 'bottom top+=44', scrub: true },
    });

    let width = el.clientWidth;
    let timer = 0;
    const ro = new ResizeObserver(() => {
      if (el.clientWidth === width) return;
      width = el.clientWidth;
      window.clearTimeout(timer);
      timer = window.setTimeout(() => ScrollTrigger.refresh(), 140);
    });
    ro.observe(el);
    let alive = true;
    void document.fonts?.ready.then(() => { if (alive) ScrollTrigger.refresh(); });
    return () => { alive = false; ro.disconnect(); window.clearTimeout(timer); live.current = null; };
  }, { scope: root, dependencies: [reduced], revertOnUpdate: true });

  const goTo = (i: number): void => {
    if (reduced) { setStop(CHAPTERS[i].id); setActive(i + 1); return; }
    const l = live.current;
    const c = l?.centers()[i + 1];
    if (!l || c === undefined) return;
    window.scrollTo({ top: l.st.start + c * (l.st.end - l.st.start), behavior: 'smooth' });
  };
  const current = reduced ? CHAPTERS.findIndex((c) => c.id === stop) + 1 : active;

  return (
    <div ref={root} className={s.root} data-mode={reduced ? 'static' : 'scroll'}>
      <div ref={journey} className={s.journey}>
        <div className={s.stage}>
          <Poster />
          <StudioCanvas
            label="Kelda Ridge at night, drawn as contour lines"
            description="A 3D landscape drawn as contour lines: a lake in the foreground, a long ridge with the walking route marked in red, stars, and bands of aurora light low in the northern sky. Scrolling moves the camera from the lake, along the ridge and up to the sky; the viewpoint buttons do the same."
            frameloop={animate ? 'always' : 'demand'}
            disabled={off3d}
            flat
            camera={{ fov: 42, near: 0.1, far: 500, position: [...VIEWPOINTS[0].position] }}
            style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }}
            fallback={
              <div className={s.fallback}>
                <Poster />
                <p className={s.fallbackNote}>A still drawing of the ridge. Every chapter below reads the same without the live scene.</p>
              </div>
            }
          >
            {palette ? <Scene palette={palette} bridge={bridge} reduced={reduced} animate={animate} stop={stop} /> : null}
          </StudioCanvas>
          <div className={s.scrim} aria-hidden="true" />
        </div>

        <div className={s.slides}>
          <header className={s.heroSlide} data-slide="">
            <p className={s.kicker}>Kelda Ridge Night Walks <span aria-hidden="true">·</span> winter season <span aria-hidden="true">·</span> sample site</p>
            <h2 className={s.title}><span className={s.t1} data-depth="">Kelda</span> <span className={s.t2} data-depth="">Ridge</span></h2>
            <p className={s.lede} data-depth="">Up here the dark has detail. Guided night walks above the treeline, from dusk until the sky does what it does.</p>
            {!reduced ? <p className={s.hint} aria-hidden="true">Scroll to walk the ridge ↓</p> : null}
          </header>
          {CHAPTERS.map((c, i) => (
            <article key={c.id} className={s.slide} data-slide="" data-side={i % 2 ? 'end' : 'start'} aria-labelledby={`kr-${c.id}`}>
              <div className={s.cap}>
                <p className={s.capIdx}><span>{String(i + 1).padStart(2, '0')} / 03</span><span>{c.time}</span></p>
                <h3 id={`kr-${c.id}`} className={s.capTitle}>{c.title}</h3>
                <p className={s.capBody}>{c.body}</p>
                <p className={s.capMeta}>{c.meta}</p>
              </div>
            </article>
          ))}
        </div>

        <div className={s.hud}>
          <nav className={s.views} aria-label="Viewpoints">
            {CHAPTERS.map((c, i) => (
              <button key={c.id} type="button" className={s.view} aria-current={current === i + 1 ? 'step' : undefined} onClick={() => goTo(i)}>
                <span className={s.viewNum} aria-hidden="true">{String(i + 1).padStart(2, '0')}</span>{c.label}
              </button>
            ))}
          </nav>
          <div className={s.ctl}>
            {!reduced ? <button type="button" className={s.toggle} aria-pressed={!playing} onClick={() => setPlaying((p) => !p)}>Pause sky</button> : null}
            <button type="button" className={s.toggle} aria-pressed={off3d} onClick={() => setOff3d((o) => !o)}>Turn off 3D</button>
          </div>
        </div>
      </div>

      <section className={s.walks} aria-labelledby="kr-walks-cap">
        <p className={s.kicker}>Winter season</p>
        <WalksTitle />
        <div className={s.tableWrap}>
          <table className={s.table}>
            <caption id="kr-walks-cap" className={s.tableCap}>Sample schedule — fictional dates and places, not bookable</caption>
            <thead><tr><th scope="col">Date</th><th scope="col">Meet</th><th scope="col">Length</th><th scope="col">Places</th></tr></thead>
            <tbody>{WALKS.map((w) => <tr key={w[0]}>{w.map((cell, i) => (i === 0 ? <th key={i} scope="row">{cell}</th> : <td key={i}>{cell}</td>))}</tr>)}</tbody>
          </table>
        </div>
      </section>

      <section className={s.bring} aria-labelledby="kr-bring">
        <h2 id="kr-bring" className={s.h2}>What to bring</h2>
        <ol className={s.bringList}>
          <li>Warm layers and a hat, even when the valley feels mild.</li>
          <li>Boots with ankle support: the path is stony near the top.</li>
          <li>A head torch with a red setting. We can lend one.</li>
          <li>Something hot to drink at the summit cairn.</li>
        </ol>
      </section>

      <section className={s.ask} aria-labelledby="kr-ask">
        <h2 id="kr-ask" className={s.askTitle}>Ask about a place on the ridge.</h2>
        <a className={s.cta} href="mailto:walks@keldaridge.example?subject=Night%20walk">Write to the guides</a>
        <p className={s.fine}>Kelda Ridge Night Walks is fictional; the schedule and places are sample data. The landscape is procedural, drawn from a seeded height field.</p>
      </section>
    </div>
  );
}

'use client';
import { useId, useMemo } from 'react';
import s from './styles.module.css';

const r1 = (n: number): number => Math.round(n * 10) / 10;

/** Ridgeline print of Kelda Ridge: stacked contour silhouettes, the route, aurora bands, stars. Theme colours via CSS. */
export function Poster({ className }: { className?: string }) {
  const id = useId();
  const art = useMemo(() => {
    const shape = (x: number, k: number) =>
      260 * Math.exp(-(((x - 980 - k * 6) / 360) ** 2)) + 150 * Math.exp(-(((x - 430 + k * 4) / 250) ** 2)) + 22 * Math.sin(x / 61 + k * 0.9) + 12 * Math.sin(x / 23 - k);
    const ridges = Array.from({ length: 15 }, (_, k) => {
      const base = 520 + k * 34;
      const amp = 0.55 + k * 0.035;
      const pts: string[] = [];
      for (let x = -20; x <= 1620; x += 20) pts.push(`${x} ${r1(base - shape(x, k) * amp)}`);
      return { d: `M${pts.join('L')}L1620 1020L-20 1020Z`, index: k % 5 === 4, top: r1(base - shape(800, k) * amp) };
    });
    const route: string[] = [];
    for (let x = 300; x <= 1340; x += 20) route.push(`${x} ${r1(520 + 9 * 34 - shape(x, 9) * (0.55 + 9 * 0.035) - 10)}`);
    let h = 9;
    const rnd = () => { h = (Math.imul(h, 1664525) + 1013904223) >>> 0; return h / 4294967296; };
    const stars = Array.from({ length: 150 }, () => ({ x: r1(rnd() * 1600), y: r1(rnd() * 470), r: r1(0.8 + rnd() * 1.7) }));
    const bands = [0, 1, 2].map((b) => {
      const top: string[] = [];
      const bottom: string[] = [];
      for (let x = 380; x <= 1500; x += 28) {
        const w = Math.sin((x - 380) / 1120 * Math.PI);
        const y = 150 + b * 70 + 40 * Math.sin(x / 140 + b) + 18 * Math.sin(x / 47 - b * 2);
        top.push(`${x} ${r1(y - 70 * w)}`);
        bottom.unshift(`${x} ${r1(y + 20 * w)}`);
      }
      return `M${top.join('L')}L${bottom.join('L')}Z`;
    });
    return { ridges, route: `M${route.join('L')}`, stars, bands };
  }, []);

  return (
    <svg className={`${s.poster} ${className ?? ''}`} viewBox="0 0 1600 1000" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id={`${id}sky`} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0" className={s.pSkyTop} />
          <stop offset="0.75" className={s.pHorizon} />
        </linearGradient>
        <linearGradient id={`${id}aur`} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0" className={s.pAurB} />
          <stop offset="0.55" className={s.pAurA} />
          <stop offset="1" className={s.pAurFade} />
        </linearGradient>
      </defs>
      <rect width="1600" height="1000" fill={`url(#${id}sky)`} />
      {art.stars.map((st, i) => <circle key={i} className={s.pStar} cx={st.x} cy={st.y} r={st.r} />)}
      {art.bands.map((d, i) => <path key={i} d={d} fill={`url(#${id}aur)`} className={s.pBand} />)}
      {art.ridges.map((r, i) => (
        <g key={i}>
          <path d={r.d} className={r.index ? s.pRidgeIndex : s.pRidge} />
          {i === 9 ? <path d={art.route} className={s.pRoute} /> : null}
        </g>
      ))}
    </svg>
  );
}

'use client';
import { useFrame, useThree } from '@react-three/fiber';
import { useEffect, useMemo, useRef } from 'react';
import {
  BackSide, BufferAttribute, BufferGeometry, CatmullRomCurve3, Color, MathUtils, MeshBasicMaterial, OctahedronGeometry,
  PlaneGeometry, ShaderMaterial, SphereGeometry, TubeGeometry, Vector3, type PerspectiveCamera,
} from 'three';
import { CameraRig, useQuality, type CameraPose } from '../../../three';
import { SIZE, VIEWPOINTS, WATER, cameraPath, height, routePoints, type StopId } from './terrain';
import { skyFrag, skyVert, starFrag, starVert, terrainFrag, terrainVert } from './shaders';

export interface Palette {
  base: string; line: string; index: string; water: string; skyTop: string; horizon: string;
  aurA: string; aurB: string; route: string; stars: string; aurora: number;
}
/** The page owns scroll progress; the scene only reads it. `u` is the camera's place on its path (0–1). */
export interface Bridge { u: number; invalidate: (() => void) | null }

const PRESETS: Record<StopId, CameraPose> = Object.fromEntries(VIEWPOINTS.map((v) => [v.id, { position: v.position, target: v.target, fov: 42 }])) as Record<StopId, CameraPose>;
const color = () => ({ value: new Color() });

/** Damped travel along the camera path; frames are requested only until the camera settles. */
function ScrollCamera({ bridge }: { bridge: Bridge }) {
  const camera = useThree((s) => s.camera) as PerspectiveCamera;
  const invalidate = useThree((s) => s.invalidate);
  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
  const path = useMemo(() => cameraPath(), []);
  const look = useMemo(() => new Vector3(), []);
  const cur = useRef(bridge.u);

  useEffect(() => { bridge.invalidate = invalidate; invalidate(); return () => { bridge.invalidate = null; }; }, [bridge, invalidate]);
  useEffect(() => {
    camera.fov = aspect < 0.8 ? 62 : aspect < 1.2 ? 50 : 42;
    camera.updateProjectionMatrix();
    invalidate();
  }, [aspect, camera, invalidate]);

  useFrame((_, dt) => {
    const goal = MathUtils.clamp(bridge.u, 0, 1);
    cur.current = MathUtils.damp(cur.current, goal, 3.4, Math.min(dt, 0.1));
    if (Math.abs(goal - cur.current) < 1e-4) cur.current = goal;
    path.pos.getPoint(cur.current, camera.position);
    path.look.getPoint(cur.current, look);
    camera.lookAt(look);
    if (cur.current !== goal) invalidate();
  });
  return null;
}

export function Scene({ palette, bridge, reduced, animate, stop }: { palette: Palette; bridge: Bridge; reduced: boolean; animate: boolean; stop: StopId }) {
  const quality = useQuality();
  const invalidate = useThree((s) => s.invalidate);
  const dpr = useThree((s) => s.viewport.dpr);
  const segs = Math.round(MathUtils.clamp(220 * quality.density, 72, 220));
  const starCount = Math.round(2600 * quality.density);

  const terrain = useMemo(() => {
    const g = new PlaneGeometry(SIZE, SIZE, segs, segs);
    g.rotateX(-Math.PI / 2);
    const p = g.attributes.position as BufferAttribute;
    for (let i = 0; i < p.count; i++) p.setY(i, height(p.getX(i), p.getZ(i)));
    p.needsUpdate = true;
    g.computeBoundingSphere();
    return g;
  }, [segs]);
  const route = useMemo(() => {
    const pts = routePoints();
    return { tube: new TubeGeometry(new CatmullRomCurve3(pts), 220, 0.042, 5, false), cairns: [pts[14], pts[72], pts[pts.length - 1]] };
  }, []);
  const stars = useMemo(() => {
    const g = new BufferGeometry();
    const pos = new Float32Array(starCount * 3);
    const seed = new Float32Array(starCount);
    let h = 12345;
    const rnd = () => { h = (Math.imul(h, 1664525) + 1013904223) >>> 0; return h / 4294967296; };
    for (let i = 0; i < starCount; i++) {
      const az = rnd() * Math.PI * 2;
      const el = Math.asin(0.05 + rnd() * 0.95);
      pos[i * 3] = Math.cos(el) * Math.sin(az) * 190;
      pos[i * 3 + 1] = Math.sin(el) * 190;
      pos[i * 3 + 2] = Math.cos(el) * Math.cos(az) * 190;
      seed[i] = rnd();
    }
    g.setAttribute('position', new BufferAttribute(pos, 3));
    g.setAttribute('aSeed', new BufferAttribute(seed, 1));
    return g;
  }, [starCount]);
  const skyGeo = useMemo(() => new SphereGeometry(200, 48, 24), []);
  const cairnGeo = useMemo(() => new OctahedronGeometry(0.2, 0), []);

  // Materials are created here so their uniforms objects are the ones we write to.
  const mats = useMemo(() => ({
    terrain: new ShaderMaterial({
      vertexShader: terrainVert, fragmentShader: terrainFrag,
      uniforms: { uBase: color(), uLine: color(), uIndex: color(), uWater: color(), uFog: color(), uInterval: { value: 0.5 }, uFogNear: { value: 16 }, uFogFar: { value: 74 }, uWaterLevel: { value: WATER } },
    }),
    sky: new ShaderMaterial({
      vertexShader: skyVert, fragmentShader: skyFrag, side: BackSide, depthWrite: false,
      uniforms: { uTop: color(), uHorizon: color(), uAurA: color(), uAurB: color(), uTime: { value: 0 }, uAur: { value: 1 } },
    }),
    stars: new ShaderMaterial({
      vertexShader: starVert, fragmentShader: starFrag, transparent: true, depthWrite: false,
      uniforms: { uColor: color(), uTime: { value: 0 }, uSize: { value: 2.4 }, uDpr: { value: 1 } },
    }),
    route: new MeshBasicMaterial({ toneMapped: false }),
  }), []);

  useEffect(() => () => { terrain.dispose(); }, [terrain]);
  useEffect(() => () => { stars.dispose(); }, [stars]);
  useEffect(() => () => {
    route.tube.dispose(); skyGeo.dispose(); cairnGeo.dispose();
    Object.values(mats).forEach((m) => m.dispose());
  }, [route, skyGeo, cairnGeo, mats]);

  useEffect(() => {
    const t = mats.terrain.uniforms;
    t.uBase.value.set(palette.base); t.uLine.value.set(palette.line); t.uIndex.value.set(palette.index);
    t.uWater.value.set(palette.water); t.uFog.value.set(palette.horizon);
    const k = mats.sky.uniforms;
    k.uTop.value.set(palette.skyTop); k.uHorizon.value.set(palette.horizon); k.uAurA.value.set(palette.aurA); k.uAurB.value.set(palette.aurB);
    k.uAur.value = palette.aurora;
    mats.stars.uniforms.uColor.value.set(palette.stars);
    mats.route.color.set(palette.route);
    invalidate();
  }, [palette, mats, invalidate]);
  useEffect(() => { mats.stars.uniforms.uDpr.value = dpr; invalidate(); }, [dpr, mats, invalidate]);

  // Ambient time only advances while the sky is playing; paused or reduced, the frame is frozen.
  useFrame((_, dt) => {
    if (!animate) return;
    mats.sky.uniforms.uTime.value += dt;
    mats.stars.uniforms.uTime.value += dt;
  });

  return (
    <>
      <mesh geometry={skyGeo} material={mats.sky} renderOrder={-1} frustumCulled={false} />
      <points geometry={stars} material={mats.stars} renderOrder={0} frustumCulled={false} />
      <mesh geometry={terrain} material={mats.terrain} />
      <mesh geometry={route.tube} material={mats.route} />
      {route.cairns.map((p, i) => <mesh key={i} geometry={cairnGeo} material={mats.route} position={[p.x, p.y + 0.24, p.z]} />)}
      {reduced ? <CameraRig presets={PRESETS} preset={stop} /> : <ScrollCamera bridge={bridge} />}
    </>
  );
}

/* GLSL for Kelda Ridge. Colours arrive as uniforms derived from the page's theme tokens. */

export const terrainVert = /* glsl */ `
varying float vH;
varying float vDepth;
varying vec3 vWorld;
void main() {
  vec4 world = modelMatrix * vec4(position, 1.0);
  vWorld = world.xyz;
  vH = position.y;
  vec4 mv = viewMatrix * world;
  vDepth = -mv.z;
  gl_Position = projectionMatrix * mv;
}`;

export const terrainFrag = /* glsl */ `
uniform vec3 uBase, uLine, uIndex, uWater, uFog;
uniform float uInterval, uFogNear, uFogFar, uWaterLevel;
varying float vH;
varying float vDepth;
varying vec3 vWorld;
float isoline(float v, float width) {
  float f = abs(fract(v - 0.5) - 0.5) / max(fwidth(v), 1e-4);
  return 1.0 - smoothstep(0.0, width, f);
}
void main() {
  float water = 1.0 - step(uWaterLevel + 0.004, vH);
  vec3 col = mix(uBase, uWater, water);
  float minor = isoline(vH / uInterval, 0.9) * (1.0 - water);
  float major = isoline(vH / (uInterval * 5.0), 1.5) * (1.0 - water);
  col = mix(col, uLine, minor * 0.7);
  col = mix(col, uIndex, major * 0.9);
  float hatch = isoline(vWorld.z * 1.4, 0.8) * water;
  col = mix(col, uLine, hatch * 0.45);
  col = mix(col, uFog, smoothstep(uFogNear, uFogFar, vDepth));
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}`;

export const skyVert = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = normalize(position);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

export const skyFrag = /* glsl */ `
uniform vec3 uTop, uHorizon, uAurA, uAurB;
uniform float uTime, uAur;
varying vec3 vDir;
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 4; i++) { v += a * noise(p); p = p * 2.03 + 11.0; a *= 0.5; }
  return v;
}
void main() {
  vec3 d = normalize(vDir);
  float y = d.y;
  vec3 col = mix(uHorizon, uTop, smoothstep(-0.04, 0.6, y));
  // Curtains of light toward the north (-z), between about 6 and 50 degrees of elevation.
  float az = atan(d.x, -d.z);
  float north = smoothstep(1.9, 0.4, abs(az));
  float drift = uTime * 0.05;
  float band = fbm(vec2(az * 2.6 + drift, drift * 0.6));
  float curtain = smoothstep(0.1, 0.24, y + band * 0.08) * (1.0 - smoothstep(0.32, 0.86, y + band * 0.12));
  float folds = 0.55 + 0.45 * sin(az * 22.0 + band * 7.0 + uTime * 0.3);
  float a = curtain * north * smoothstep(0.38, 0.72, band) * folds * uAur;
  vec3 aur = mix(uAurA, uAurB, smoothstep(0.16, 0.6, y));
  col = mix(col, aur, clamp(a, 0.0, 1.0) * 0.82);
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}`;

export const starVert = /* glsl */ `
attribute float aSeed;
uniform float uTime, uSize, uDpr;
varying float vTwinkle;
void main() {
  vTwinkle = 0.6 + 0.4 * sin(uTime * (0.5 + aSeed * 1.6) + aSeed * 40.0);
  gl_PointSize = uSize * uDpr * (0.55 + aSeed * 0.9);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

export const starFrag = /* glsl */ `
uniform vec3 uColor;
varying float vTwinkle;
void main() {
  float d = length(gl_PointCoord - 0.5);
  float a = smoothstep(0.5, 0.12, d) * vTwinkle;
  if (a < 0.03) discard;
  gl_FragColor = vec4(uColor, a);
  #include <colorspace_fragment>
}`;

/*
 * Kelda Ridge Night Walks — a survey print that comes alive. The landscape is drawn as contour lines; in the light
 * theme it is ink on paper at dawn, in the dark theme pale lines on night with the aurora at full strength. Type is
 * Bricolage at two extreme weights (300 / 700) layered in depth; captions sit on solid panels above the canvas.
 */
.root {
  --kr-pad: clamp(16px, 4cqi, 64px);
  --kr-base: var(--s3-bg, #f3f0e8);
  --kr-water: var(--s3-surface-2, #e9e5da);
  --kr-sky-top: var(--s3-surface-2, #e9e5da);
  --kr-horizon: var(--s3-bg, #f3f0e8);
  --kr-aur-a: var(--s3-accent-data, #0a6e4d);
  --kr-aur-b: var(--s3-signal, #bf2f09);
  --kr-aurora: 1.5;
  position: relative;
  overflow-x: clip;
  background: var(--s3-bg, #f3f0e8);
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
}
:global([data-theme='dark']) .root {
  --kr-base: #0b0c0b;
  --kr-water: #131614;
  --kr-sky-top: #050606;
  --kr-horizon: #1e201c;
  --kr-aurora: 1;
}

.kicker, .capIdx, .capMeta, .hint, .tableCap, .viewNum {
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ── The journey: sticky stage behind scrolling slides ──────── */
.journey { position: relative; }
.stage { position: sticky; top: 44px; z-index: 0; height: calc(100svh - 44px); overflow: clip; background: var(--kr-horizon); }
.poster { position: absolute; inset: 0; display: block; width: 100%; height: 100%; }
.scrim { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, color-mix(in oklab, var(--kr-sky-top) 78%, transparent) 0%, transparent 42%); }
.slides { position: relative; z-index: 1; margin-top: calc(-100svh + 44px); }

.heroSlide { display: grid; align-content: start; gap: clamp(14px, 2cqi, 24px); min-height: calc(100svh - 44px); padding: clamp(28px, 5cqi, 72px) var(--kr-pad) 0; }
.title {
  display: grid;
  margin: 0;
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(4.2rem, 0.8rem + 15.5cqi, 16.5rem);
  line-height: 0.8;
  letter-spacing: -0.055em;
}
.t1, .t2, .lede { display: block; will-change: transform; }
.t1 { font-weight: 300; }
.t2 { padding-inline-start: 0.62em; font-weight: 700; letter-spacing: -0.06em; }
.lede {
  max-width: 27ch;
  margin: 8px 0 0;
  font-family: var(--s3-font-serif, Georgia, serif);
  font-size: clamp(1.3rem, 0.95rem + 1.4cqi, 2.1rem);
  line-height: 1.16;
  text-wrap: balance;
}
.hint { color: var(--s3-ink, #11110f); }

.slide { display: grid; align-items: center; min-height: 120svh; padding: 0 var(--kr-pad); }
.slide[data-side='end'] { justify-items: end; }
.cap {
  display: grid;
  gap: 12px;
  width: min(100%, 27rem);
  padding: clamp(18px, 2.4cqi, 28px);
  background: var(--s3-surface, #fbf9f4);
  border: 1px solid var(--s3-line, #11110f24);
  border-radius: var(--s3-radius-m, 10px);
}
.capIdx { display: flex; justify-content: space-between; color: var(--s3-ink-muted, #5c5a52); }
.capTitle { margin: 0; font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif); font-size: clamp(1.75rem, 1.1rem + 1.8cqi, 2.6rem); font-weight: 700; line-height: 1; letter-spacing: -0.035em; }
.capBody { margin: 0; font-size: 1rem; line-height: 1.55; }
.capMeta { padding-top: 10px; border-top: 1px solid var(--s3-line, #11110f24); color: var(--s3-ink-muted, #5c5a52); }

/* Controls: sticky to the bottom of the viewport for as long as the journey lasts */
.hud {
  position: sticky;
  bottom: 14px;
  z-index: 3;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: end;
  gap: 10px;
  margin-top: -76px;
  padding: 0 var(--kr-pad) 14px;
  pointer-events: none;
}
.views, .ctl {
  display: flex;
  gap: 4px;
  padding: 5px;
  background: var(--s3-surface, #fbf9f4);
  border: 1px solid var(--s3-line, #11110f24);
  border-radius: 999px;
  pointer-events: auto;
}
.view, .toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 14px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
}
.view:hover, .toggle:hover { background: var(--s3-surface-2, #e9e5da); }
.view[aria-current], .toggle[aria-pressed='true'] { background: var(--s3-ink, #11110f); color: var(--s3-bg, #f3f0e8); }
.view:focus-visible, .toggle:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.viewNum { font-size: 0.625rem; letter-spacing: 0.06em; }
@container (max-width: 34rem) {
  .hud { flex-direction: column; align-items: flex-start; gap: 6px; margin-top: -92px; }
  .views, .ctl { padding: 3px; }
  .view, .toggle { min-height: 32px; padding: 0 11px; }
  .viewNum { display: none; }
}

.fallback { position: absolute; inset: 0; }
.fallbackNote {
  position: absolute;
  left: var(--kr-pad);
  bottom: 96px;
  max-width: 34ch;
  margin: 0;
  padding: 10px 14px;
  background: var(--s3-surface, #fbf9f4);
  border: 1px solid var(--s3-line, #11110f24);
  border-radius: var(--s3-radius-m, 10px);
  font-size: 0.875rem;
  line-height: 1.45;
  color: var(--s3-ink, #11110f);
}

/* Poster: the same palette as the live scene, drawn as a ridgeline print */
.pSkyTop { stop-color: var(--kr-sky-top); }
.pHorizon { stop-color: var(--kr-horizon); }
.pAurB { stop-color: var(--kr-aur-b); stop-opacity: calc(var(--kr-aurora) * 0.32); }
.pAurA { stop-color: var(--kr-aur-a); stop-opacity: calc(var(--kr-aurora) * 0.62); }
.pAurFade { stop-color: var(--kr-aur-a); stop-opacity: 0; }
.pStar { fill: var(--s3-ink, #11110f); }
.pRidge { fill: var(--kr-base); stroke: var(--s3-ink-muted, #5c5a52); stroke-width: 1.2; }
.pRidgeIndex { fill: var(--kr-base); stroke: var(--s3-ink, #11110f); stroke-width: 1.8; }
.pRoute { fill: none; stroke: var(--s3-signal, #bf2f09); stroke-width: 3; stroke-dasharray: 2 10; stroke-linecap: round; }

/* ── After the journey: plain, still content ────────────────── */
.walks, .bring, .ask {
  position: relative;
  z-index: 1;
  padding: clamp(72px, 10cqi, 160px) var(--kr-pad);
  border-top: 1px solid var(--s3-line, #11110f24);
