}
.walks { display: grid; gap: 28px; }
.walks .kicker { color: var(--s3-ink-muted, #5c5a52); }
.walksTitle h2, .placeholder, .h2, .askTitle {
  max-width: 13ch;
  margin: 0;
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(2.6rem, 1rem + 6cqi, 7rem);
  font-weight: 300;
  line-height: 0.92;
  letter-spacing: -0.045em;
  color: var(--s3-ink, #11110f);
}
.placeholder { opacity: 0; }
.table { width: 100%; max-width: 60rem; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.tableCap { padding-bottom: 12px; caption-side: top; text-align: start; color: var(--s3-ink-muted, #5c5a52); }
.table th, .table td { padding: 14px 12px 14px 0; border-bottom: 1px solid var(--s3-line, #11110f24); font-size: 1rem; font-weight: 400; text-align: start; }
.table thead th { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.table tbody th { font-weight: 600; }
@container (max-width: 30rem) { .table th, .table td { padding-right: 8px; font-size: 0.875rem; } }

.bring { display: grid; gap: 32px; }
@container (min-width: 56rem) { .bring { grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr); align-items: start; } }
.h2 { font-size: clamp(2.2rem, 1rem + 4cqi, 5rem); }
.bringList { display: grid; gap: 0; margin: 0; padding: 0; list-style: none; counter-reset: bring; border-top: 1px solid var(--s3-line, #11110f24); }
.bringList li { display: grid; grid-template-columns: 3rem minmax(0, 1fr); gap: 12px; padding: 16px 0; border-bottom: 1px solid var(--s3-line, #11110f24); font-size: 1.0625rem; line-height: 1.5; counter-increment: bring; }
.bringList li::before { content: counter(bring, decimal-leading-zero); font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.75rem; padding-top: 0.3em; color: var(--s3-signal, #bf2f09); }

.ask { display: grid; gap: 24px; justify-items: start; }
.askTitle { font-size: clamp(2.4rem, 1rem + 5cqi, 6rem); }
.cta {
  display: inline-flex;
  align-items: center;
  min-height: 52px;
  padding: 0 28px;
  border-radius: 999px;
  background: var(--s3-ink, #11110f);
  color: var(--s3-bg, #f3f0e8);
  font-weight: 600;
  text-decoration: none;
}
.cta:hover { background: var(--s3-signal, #bf2f09); color: var(--s3-on-signal, #fff); }
.cta:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 3px; }
.fine { max-width: 60ch; margin: 0; font-size: 0.8125rem; line-height: 1.5; color: var(--s3-ink-muted, #5c5a52); }

/* ── Reduced motion: a still page; the viewpoint buttons cut the camera ── */
.root[data-mode='static'] .journey { display: flex; flex-direction: column; }
.root[data-mode='static'] .slides { display: contents; }
.root[data-mode='static'] .heroSlide { order: 0; min-height: 0; padding-bottom: 28px; }
.root[data-mode='static'] .stage { order: 1; position: relative; top: auto; height: 68svh; margin: 0 var(--kr-pad); border: 1px solid var(--s3-line, #11110f24); border-radius: var(--s3-radius-l, 18px); }
.root[data-mode='static'] .scrim { display: none; }
.root[data-mode='static'] .hud { order: 2; position: static; margin: 14px 0 0; padding-bottom: 0; }
.root[data-mode='static'] .slide { order: 3; min-height: 0; padding: 20px var(--kr-pad) 0; justify-items: start; }
.root[data-mode='static'] .slide:last-of-type { padding-bottom: 56px; }

/**
 * Kelda Ridge (fictional): a deterministic height field, the walking route and the camera path.
 * Runs on the client only (inside the canvas), so floating-point output never meets server HTML.
 */
import { CatmullRomCurve3, Vector3 } from 'three';

export const SIZE = 64; // world units across the terrain square
export const WATER = 0.32;

const fract = (v: number): number => v - Math.floor(v);
function hash(ix: number, iz: number): number {
  let h = Math.imul(ix | 0, 374761393) + Math.imul(iz | 0, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
function noise(x: number, z: number): number {
  const ix = Math.floor(x);
  const iz = Math.floor(z);
  const fx = fract(x);
  const fz = fract(z);
  const ux = fx * fx * (3 - 2 * fx);
  const uz = fz * fz * (3 - 2 * fz);
  const a = hash(ix, iz);
  const b = hash(ix + 1, iz);
  const c = hash(ix, iz + 1);
  const d = hash(ix + 1, iz + 1);
  return a + (b - a) * ux + (c - a) * uz + (a - b - c + d) * ux * uz;
}
function fbm(x: number, z: number): number {
  let v = 0;
  let amp = 0.5;
  for (let i = 0; i < 4; i++) { v += amp * noise(x, z); x = x * 2.03 + 17.1; z = z * 2.03 - 9.4; amp *= 0.5; }
  return v;
}

/** The ridge line runs roughly west–east across the middle of the map. */
export const ridgeZ = (x: number): number => -6 + 0.22 * x + 2.2 * Math.sin(0.21 * x);

export function height(x: number, z: number): number {
  const d = z - ridgeZ(x);
  const crest = 6.2 + 1.6 * Math.sin(0.13 * x + 1) + 1.1 * Math.sin(0.31 * x - 0.4);
  let h = crest * Math.exp(-(d * d) / (2 * 4.6 * 4.6));
  h -= 2.8 * Math.exp(-((x + 4) * (x + 4) + (z - 13) * (z - 13)) / (2 * 5.2 * 5.2)); // the lake basin
  h += Math.max(0, -z - 12) * 0.42; // far fells behind the ridge
  h += 1.5 * (fbm(x * 0.11 + 3, z * 0.11) - 0.5) + 0.55 * (fbm(x * 0.36, z * 0.36 + 5) - 0.5);
  return Math.max(WATER, h + 1.25);
}

/** The marked path: lake shore → up the shoulder → along the crest. */
export function routePoints(): Vector3[] {
  const xz: [number, number][] = [[-7, 9.6], [-4.6, 6.2], [-2, 2.4], [0.5, -0.6], [3, ridgeZ(3)], [6, ridgeZ(6)], [9, ridgeZ(9)], [12, ridgeZ(12)], [15, ridgeZ(15) + 0.3]];
  const coarse = new CatmullRomCurve3(xz.map(([x, z]) => new Vector3(x, 0, z)));
  return coarse.getSpacedPoints(160).map((p) => new Vector3(p.x, height(p.x, p.z) + 0.1, p.z));
}

export type StopId = 'overview' | 'lake' | 'ridge' | 'sky';

export interface Viewpoint { id: StopId; position: [number, number, number]; target: [number, number, number] }

/** Camera stops in story order; the scroll camera travels through all four, the step buttons cut between the last three. */
export const VIEWPOINTS: readonly Viewpoint[] = [
  { id: 'overview', position: [0, 13.5, 31], target: [0, 3.2, -6] },
  { id: 'lake', position: [-10.5, 2.6, 18.5], target: [1.5, 3.6, 1] },
  { id: 'ridge', position: [2.2, 10.6, 2.6], target: [14, 8.2, -4.5] },
  { id: 'sky', position: [7.5, 12.4, -1.2], target: [5, 27, -42] },
];

export const cameraPath = (): { pos: CatmullRomCurve3; look: CatmullRomCurve3 } => ({
  pos: new CatmullRomCurve3(VIEWPOINTS.map((v) => new Vector3(...v.position)), false, 'centripetal'),
  look: new CatmullRomCurve3(VIEWPOINTS.map((v) => new Vector3(...v.target)), false, 'centripetal'),
});
